std::decay_t<decltype(source)> result;
for (const auto& entry : source) if (std::find(keys.begin(), keys.end(), entry.first) == keys.end()) result[entry.first] = entry.second;
return result;

languages.rust:
let mut result = vgraph::Map::new();
for key in source.keys() {
    if !keys.contains(&key) {
        if let Some(value) = source.get(&key) { result.insert(key, value); }
    }
}
return result;

